import{_ as o,l as i,o as t,c as s,v as d,p as h,x as l,d as r,i as m,S as p,b as e}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"HGRN","description":"","frontmatter":{"title":"HGRN","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/hgrn.md","filePath":"llm/hgrn.md","lastUpdated":1789023840000}'),u={name:"llm/hgrn.md"};function c(N,a,E,_,f,B){const n=i("Mermaid");return t(),s("div",null,[a[1]||(a[1]=d('<h1 id="hgrn" tabindex="-1">HGRN <a class="header-anchor" href="#hgrn" aria-label="Permalink to &quot;HGRN&quot;">​</a></h1><div class="epigraph"><p>用层级衰减门让浅层快忘、深层慢忘，在线性递归里做出多时间尺度，而不走注意力。</p><footer>—— Qin et al., Hierarchically Gated Recurrent Neural Network for Sequence Modeling, NeurIPS 2023</footer></div><p><a href="/llm/gated-linear-attention">上一课</a>的状态是键值外积矩阵，遗忘门作用在这份矩阵上。更老、更窄的路线是：状态就是向量，门是对角或标量，把 RNN 做强。HGRN（Hierarchically Gated RNN）把<strong>层级时间尺度</strong>写进门的结构：层越深，门越倾向保持。本课补这条，是为了后课 delta rule、TTT 仍有一个「向量状态 RNN」的参照，也避免把所有线性模型都说成 GLA。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GLA 与对角 SSM 都能多尺度，但多尺度来自不同头或不同通道的独立门。人若希望<strong>深度本身编码时间尺度</strong>——浅层处理局部，深层持有篇章——需要门的先验随层变，而不是等优化自己发现。缺口是一种显式层级门控：层次 \\(l\\) 的遗忘下限更高，强制长程信息走深层递归。</p><p>HGRN 不是 SSM 的 HiPPO 矩阵，也不是 softmax。它是门控 RNN 族，训练用并行扫描（门在对角时结合），推理常数状态。复杂度与 Mamba 同类，归纳偏置不同。</p><p><span class="marginnote">HGRN2 把若干点改到更接近线性注意力。本课以层级门为主，不把版本号写成另一课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每层每通道，\\(h_t=\\mu_t\\odot h_{t-1}+(1-\\mu_t)\\odot \\tilde{x}_t\\)，其中 \\(\\mu_t=\\sigma(\\cdot)\\) 且被加一个随层增加的下界或偏置，使深层 \\(\\mu\\) 更接近 1。输入 \\(\\tilde{x}_t\\) 来自前一层输出的投影。可以再加输出门。整网叠多层这种递归，层间仍残差。</p><p>并行化：\\(\\mu_t\\) 只依赖当前输入时，对 \\(h\\) 是对角仿射，走<a href="/llm/chunked-parallel-form">分块并行</a>。若门依赖 \\(h_{t-1}\\)，结合律变复杂，往往禁止，以保住训练核。</p><h3 id="与-lstm-gru-的课序位置" tabindex="-1">与 LSTM / GRU 的课序位置 <a class="header-anchor" href="#与-lstm-gru-的课序位置" aria-label="Permalink to &quot;与 LSTM / GRU 的课序位置&quot;">​</a></h3><p>LSTM 的门依赖上一隐状态，难以扫描并行，大模型训练不用它当主干。HGRN 把门限制成输入依赖加层级先验，换取可并行。这是「RNN 要进 LLM 主干」必须付的结构税，与 Mamba 限制 \\(A\\) 为对角同类。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>层级下界相当于手工 curriculum：深层无法选择完全重置，长程 token 更可能活过浅层的快门。浅层则允许低 \\(\\mu\\)，快速跟踪局部语法。相对 HiPPO 的多项式基，这里不声称最优投影，只声称深度对齐时间常数，好初始化、好优化。</p><p>容量上向量状态是 \\(\\Theta(d)\\) 每层，比 GLA 的 \\(\\Theta(d^2)\\) 小，比「一层对角 SSM 扩到很大 \\(N\\)」更依赖<strong>叠层</strong>来加记忆。混合架构里 HGRN 块常插在注意力块之间当便宜的局部/中程滤波器。不要把它与 <a href="/llm/mamba">Mamba</a> 的选择性对角通道互换：HGRN 的层级先验写在深度上，Mamba 的选择写在时间步的 \\(\\Delta_t\\) 上，可以叠，但不是同一旋钮。</p><p><span class="marginnote">层级先验过强会让深层学不会遗忘过时篇章状态（话题切换）。下界应是弱偏置，不是把 \\(\\mu\\) 钉死在 0.99。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>HGRN 不提供内容寻址表，精确召回仍弱。不要与 HiPPO 的「最优记忆」口号互换引用。把 LSTM 换上扫描核却保留 \\(h\\) 依赖门，不是 HGRN，也通常训不动大宽度。下一课 delta 规则会把更新从「插值遗忘」改成「用新键擦除旧关联」，那是联想记忆，不是层级时间尺度。</p>',18)),(t(),h(p,null,{default:l(()=>[m(n,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E8%BE%93%E5%85%A5%22%5D%20--%3E%20S%5B%22%E6%B5%85%E5%B1%82%E5%BF%AB%E9%97%A8%E9%80%92%E5%BD%92%22%5D%0A%20%20S%20--%3E%20D%5B%22%E6%B7%B1%E5%B1%82%E6%85%A2%E9%97%A8%E9%80%92%E5%BD%92%22%5D%0A%20%20D%20--%3E%20Y%5B%22%E8%BE%93%E5%87%BA%22%5D%0A%20%20P%5B%22%E5%B1%82%E7%BA%A7%E9%97%A8%E4%B8%8B%E7%95%8C%22%5D%20--%3E%20D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[r("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"HGRN 用随深度变强的遗忘下界，在可扫描 RNN 里强制多时间尺度。"),e("li",null,"门须主要依赖输入，才能走分块并行；依赖 \\(h\\) 的 LSTM 式门不在本课。"),e("li",null,"向量状态省容量、弱于矩阵状态与注意力表；深度用来堆时间常数。"),e("li",null,"先验过强会损害话题切换时的遗忘。"),e("li",null,"出处：Qin et al., NeurIPS 2023。")],-1))])}const S=o(u,[["render",c]]);export{R as __pageData,S as default};
